//! 编排层 (oas-manager) —— CRI 层的上游契约。
//!
//! 这里只定义 `Manager` 公开 API（trait）、领域 request/response 类型与统一错误
//! `OasError`，外加一个 `StubManager` 供 `oas-cri` 在 §3.2 真 Manager 落地前装配起
//! 服务。真 Manager 实现（持 driver/net/storage/store 四个 trait、状态机、reconcile）
//! 在 §3.2。
//!
//! 依赖方向：`oas-cri → oas-manager → oas-types`，单向无环。本 crate 契约只依赖
//! `oas-types`，不直接依赖 driver/net/storage/store（下层错误在真 Manager impl 里
//! 映射进 `OasError`）。

use std::collections::HashMap;

use oas_types::{
    ContainerFilter, ContainerMetadata, ContainerRecord, DnsConfig, KeyValue, LinuxResources,
    Mount, SandboxFilter, SandboxMetadata, SandboxRecord,
};

// ---------------------------------------------------------------------------
// 统一领域错误
// ---------------------------------------------------------------------------

/// 统一领域错误。CRI 层 `error.rs` 把它映射成 `tonic::Status`（§3.1）。
///
/// 自包含：不 `From` 下层 `StoreError`/`DriverError`/…，以免本契约反向依赖下层 crate。
/// 下层错误在真 Manager impl 里映射进这里的变体。
#[derive(Debug, thiserror::Error)]
pub enum OasError {
    #[error("not found: {0}")]
    NotFound(String),
    #[error("image not in whitelist: {0}")]
    ImageNotInList(String),
    #[error("type mismatch: {0}")]
    TypeMismatch(String),
    #[error("invalid argument: {0}")]
    InvalidArgument(String),
    #[error("conflict: {0}")]
    Conflict(String),
    #[error("unavailable: {0}")]
    Unavailable(String),
    #[error("internal: {0}")]
    Internal(String),
}

// ---------------------------------------------------------------------------
// 领域 request / response 类型（proto ⇄ domain 的 domain 侧）
// ---------------------------------------------------------------------------

/// `RunPodSandbox` 的领域请求。annotation 里的 `agent-sandbox/type`、`cloud-disk`、
/// `rw-size`（§9）由 CRI convert 解析进 `type_id`/`cloud_disk_ref`/`rw_size`。
#[derive(Debug, Clone)]
pub struct CreateSandboxRequest {
    pub metadata: SandboxMetadata,
    pub labels: HashMap<String, String>,
    pub annotations: HashMap<String, String>,
    pub hostname: String,
    pub log_directory: String,
    pub dns_config: Option<DnsConfig>,
    pub cgroup_parent: String,
    /// 从 annotation `agent-sandbox/type` 解析。
    pub type_id: u8,
    /// 从 annotation `agent-sandbox/cloud-disk` 解析（type2 必填）。
    pub cloud_disk_ref: Option<String>,
    /// 从 annotation `agent-sandbox/rw-size` 解析。
    pub rw_size: Option<u64>,
}

/// `CreateContainer` 的领域请求。
#[derive(Debug, Clone)]
pub struct CreateContainerRequest {
    pub pod_sandbox_id: String,
    pub metadata: ContainerMetadata,
    pub image: String,
    pub command: Vec<String>,
    pub args: Vec<String>,
    pub working_dir: String,
    pub envs: Vec<KeyValue>,
    pub mounts: Vec<Mount>,
    pub labels: HashMap<String, String>,
    pub annotations: HashMap<String, String>,
    pub log_path: String,
    pub resources: LinuxResources,
    pub tty: bool,
    pub stdin: bool,
    pub stdin_once: bool,
}

/// 镜像信息（对应 CRI `Image`）。
#[derive(Debug, Clone)]
pub struct ImageInfo {
    pub id: String,
    pub repo_tags: Vec<String>,
    pub repo_digests: Vec<String>,
    pub size: u64,
    pub username: String,
    /// 工作镜像引用（= `ImageSpec.image`）。
    pub image_ref: String,
    pub pinned: bool,
}

/// `Version` 返回。
#[derive(Debug, Clone)]
pub struct VersionInfo {
    pub runtime_name: String,
    pub runtime_version: String,
    pub runtime_api_version: String,
}

/// `Status` 的运行时 condition。
#[derive(Debug, Clone)]
pub struct RuntimeCondition {
    pub r#type: String,
    pub status: bool,
    pub reason: String,
    pub message: String,
}

/// `Status` 返回。
#[derive(Debug, Clone)]
pub struct RuntimeStatusInfo {
    pub conditions: Vec<RuntimeCondition>,
}

// ---------------------------------------------------------------------------
// Manager 公开 API（CRI → manager）
// ---------------------------------------------------------------------------

/// 编排层对 CRI 层的统一入口（Facade，§5）。CRI 持 `Arc<dyn Manager>`。
///
/// 方法返回 `oas-types` 的 `SandboxRecord`/`ContainerRecord`，由 CRI convert 翻译回 proto。
#[async_trait::async_trait]
pub trait Manager: Send + Sync {
    async fn version(&self) -> Result<VersionInfo, OasError>;
    async fn status(&self) -> Result<RuntimeStatusInfo, OasError>;
    async fn update_runtime_config(&self, pod_cidr: Option<&str>) -> Result<(), OasError>;

    async fn run_sandbox(&self, req: CreateSandboxRequest) -> Result<String, OasError>;
    async fn stop_sandbox(&self, sandbox_id: &str) -> Result<(), OasError>;
    async fn remove_sandbox(&self, sandbox_id: &str) -> Result<(), OasError>;
    async fn sandbox_status(&self, sandbox_id: &str) -> Result<SandboxRecord, OasError>;
    async fn list_sandboxes(&self, filter: SandboxFilter) -> Result<Vec<SandboxRecord>, OasError>;

    async fn create_container(&self, req: CreateContainerRequest) -> Result<String, OasError>;
    async fn start_container(&self, container_id: &str) -> Result<(), OasError>;
    async fn stop_container(&self, container_id: &str, timeout: i64) -> Result<(), OasError>;
    async fn remove_container(&self, container_id: &str) -> Result<(), OasError>;
    async fn container_status(&self, container_id: &str) -> Result<ContainerRecord, OasError>;
    async fn list_containers(
        &self,
        filter: ContainerFilter,
    ) -> Result<Vec<ContainerRecord>, OasError>;

    async fn image_status(&self, image: &str) -> Result<Option<ImageInfo>, OasError>;
    async fn pull_image(&self, image: &str) -> Result<String, OasError>;
    async fn list_images(&self) -> Result<Vec<ImageInfo>, OasError>;
    async fn remove_image(&self, image: &str) -> Result<(), OasError>;
}

// ---------------------------------------------------------------------------
// StubManager：§3.2 真 Manager 落地前的装配占位
// ---------------------------------------------------------------------------

/// 空实现 Manager：握手类（version/status）返回固定值；读路径返回空；幂等 stop/remove
/// 返回 `Ok`；写操作返回 `Unavailable`（kubelet 起沙箱会失败，预期，待 §3.2）。
#[derive(Debug, Default, Clone, Copy)]
pub struct StubManager;

impl StubManager {
    pub fn new() -> Self {
        Self
    }
}

#[async_trait::async_trait]
impl Manager for StubManager {
    async fn version(&self) -> Result<VersionInfo, OasError> {
        Ok(VersionInfo {
            runtime_name: "only-agent-sandbox".into(),
            runtime_version: "0.1.0".into(),
            runtime_api_version: "v1".into(),
        })
    }

    async fn status(&self) -> Result<RuntimeStatusInfo, OasError> {
        Ok(RuntimeStatusInfo {
            conditions: vec![
                RuntimeCondition {
                    r#type: "RuntimeReady".into(),
                    status: true,
                    reason: "".into(),
                    message: "".into(),
                },
                RuntimeCondition {
                    r#type: "NetworkReady".into(),
                    status: true,
                    reason: "".into(),
                    message: "".into(),
                },
            ],
        })
    }

    async fn update_runtime_config(&self, _pod_cidr: Option<&str>) -> Result<(), OasError> {
        // 空实现接住（§3.1）。
        Ok(())
    }

    async fn run_sandbox(&self, _req: CreateSandboxRequest) -> Result<String, OasError> {
        Err(OasError::Unavailable(
            "manager not implemented (§3.2)".into(),
        ))
    }

    async fn stop_sandbox(&self, _sandbox_id: &str) -> Result<(), OasError> {
        // 幂等：删不存在 = Ok。
        Ok(())
    }

    async fn remove_sandbox(&self, _sandbox_id: &str) -> Result<(), OasError> {
        Ok(())
    }

    async fn sandbox_status(&self, sandbox_id: &str) -> Result<SandboxRecord, OasError> {
        Err(OasError::NotFound(sandbox_id.into()))
    }

    async fn list_sandboxes(&self, _filter: SandboxFilter) -> Result<Vec<SandboxRecord>, OasError> {
        Ok(Vec::new())
    }

    async fn create_container(&self, _req: CreateContainerRequest) -> Result<String, OasError> {
        Err(OasError::Unavailable(
            "manager not implemented (§3.2)".into(),
        ))
    }

    async fn start_container(&self, container_id: &str) -> Result<(), OasError> {
        Err(OasError::NotFound(container_id.into()))
    }

    async fn stop_container(&self, _container_id: &str, _timeout: i64) -> Result<(), OasError> {
        Ok(())
    }

    async fn remove_container(&self, _container_id: &str) -> Result<(), OasError> {
        Ok(())
    }

    async fn container_status(&self, container_id: &str) -> Result<ContainerRecord, OasError> {
        Err(OasError::NotFound(container_id.into()))
    }

    async fn list_containers(
        &self,
        _filter: ContainerFilter,
    ) -> Result<Vec<ContainerRecord>, OasError> {
        Ok(Vec::new())
    }

    async fn image_status(&self, _image: &str) -> Result<Option<ImageInfo>, OasError> {
        Ok(None)
    }

    async fn pull_image(&self, _image: &str) -> Result<String, OasError> {
        Err(OasError::Unavailable(
            "manager not implemented (§3.2)".into(),
        ))
    }

    async fn list_images(&self) -> Result<Vec<ImageInfo>, OasError> {
        Ok(Vec::new())
    }

    async fn remove_image(&self, _image: &str) -> Result<(), OasError> {
        Ok(())
    }
}

//! 跨 crate 共享领域模型（§4 `oas-types`）。
//!
//! 无重依赖，只靠 serde。`SandboxRecord` / `ContainerRecord` 等为持久化层
//! (`Store` trait) 与编排层共享的事实源载体，字段原样透传（§6 红线 1）。

use std::collections::HashMap;

// ---------------------------------------------------------------------------
// IPAM 租约（net 与 store 共用）
// ---------------------------------------------------------------------------

/// IPAM 分配的 IP 租约。崩溃后不可重复分配（§3.6 `ipam` 表）。
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct IpLease {
    /// 分配到的 IP，如 `10.244.1.5`。
    pub ip: String,
    /// 所属 CIDR，如 `10.244.1.0/24`。
    pub cidr: String,
    /// 持有该租约的 sandbox。
    pub sandbox_id: String,
}

// ---------------------------------------------------------------------------
// 状态枚举（映射 CRI proto state）
// ---------------------------------------------------------------------------

/// 映射 `PodSandboxStatus.state`（§3.2 Sandbox FSM）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum SandboxState {
    Ready,
    NotReady,
}

/// 映射 `ContainerStatus.state`（§3.2 Container FSM）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum ContainerState {
    Created,
    Running,
    Exited,
    Unknown,
}

/// 带外 agent 回灌的进程退出 reason（§21.4）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum ContainerExitReason {
    Completed,
    Error,
    OomKilled,
}

// ---------------------------------------------------------------------------
// 原样透传的 CRI metadata / 资源（轻量自有类型，不引 proto）
// ---------------------------------------------------------------------------

/// `PodSandboxMetadata`，原样存取（§6 红线 1）。
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct SandboxMetadata {
    pub name: String,
    pub namespace: String,
    /// Pod UID。
    pub uid: String,
    pub attempt: u32,
}

/// `ContainerMetadata`，原样存取。
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct ContainerMetadata {
    pub name: String,
    pub attempt: u32,
}

/// 挂载传播模式（对应 CRI `MountPropagation`）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum MountPropagation {
    Private,
    HostToContainer,
    Bidirectional,
}

/// 挂载项（轻量自有类型）。
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct Mount {
    pub container_path: String,
    pub host_path: String,
    pub read_only: bool,
    pub propagation: MountPropagation,
}

/// Linux 资源限制（轻量，供 §9 type 表一致性校验）。
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
pub struct LinuxResources {
    pub cpu_shares: Option<u64>,
    pub memory_limit_bytes: Option<i64>,
}

/// 环境变量键值对（对应 CRI `KeyValue`）。
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct KeyValue {
    pub key: String,
    pub value: String,
}

/// DNS 配置（对应 CRI `DNSConfig`，§13 注入 guest `/etc/resolv.conf`）。
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
pub struct DnsConfig {
    pub servers: Vec<String>,
    pub searches: Vec<String>,
    pub options: Vec<String>,
}

// ---------------------------------------------------------------------------
// Records（持久化层事实源，§3.6 五张表中的 sandbox / container）
// ---------------------------------------------------------------------------

/// `sandbox` 表记录。`pod_uid` 为 ★幂等键；metadata/labels/annotations 原样。
///
/// 注意：`vm_id` 用 `u64` 而非 `oas_driver::VmId`，避免 `oas-types` 反向依赖
/// `oas-driver`。
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct SandboxRecord {
    pub sandbox_id: String,
    /// ★幂等键（kubelet 重试不产生重复 VM）。
    pub pod_uid: String,
    pub metadata: SandboxMetadata,
    pub labels: HashMap<String, String>,
    pub annotations: HashMap<String, String>,
    pub type_id: u8,
    pub vm_id: u64,
    pub netns_path: String,
    pub tap_name: String,
    pub mac: String,
    pub pod_ip: String,
    pub gateway: String,
    pub rw_layer_path: Option<String>,
    pub cloud_disk_dev: Option<String>,
    pub state: SandboxState,
    /// Unix 时间戳（秒）。
    pub created_at: i64,
}

/// `container` 表记录。`exit_code` / `reason` / `message` 由带外 agent 回灌（§21.4）。
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct ContainerRecord {
    pub container_id: String,
    pub sandbox_id: String,
    pub metadata: ContainerMetadata,
    /// 工作镜像引用，须命中该 type 的 `image_whitelist`（§9）。
    pub image: String,
    pub command: Vec<String>,
    pub args: Vec<String>,
    /// `KEY=VAL` 形式。
    pub env: Vec<String>,
    pub mounts: Vec<Mount>,
    pub resources: LinuxResources,
    pub state: ContainerState,
    pub created_at: i64,
    pub started_at: Option<i64>,
    pub finished_at: Option<i64>,
    /// 进程退出码（带外 agent 回灌；收不到则 state=UNKNOWN，严禁反推 0）。
    pub exit_code: i32,
    pub reason: Option<ContainerExitReason>,
    pub message: String,
    pub labels: HashMap<String, String>,
    pub annotations: HashMap<String, String>,
}

// ---------------------------------------------------------------------------
// Filters（List* 收敛，§21.3）
// ---------------------------------------------------------------------------

/// `list_sandboxes` 过滤器：按 id / pod_uid / label / state 收敛。
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
pub struct SandboxFilter {
    pub id: Option<String>,
    pub pod_uid: Option<String>,
    pub label_selector: HashMap<String, String>,
    pub state: Option<SandboxState>,
}

/// `list_containers` 过滤器：按 id / sandbox_id / label / state 收敛。
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
pub struct ContainerFilter {
    pub id: Option<String>,
    pub sandbox_id: Option<String>,
    pub label_selector: HashMap<String, String>,
    pub state: Option<ContainerState>,
}

//! 编排层 → Firecracker 原语层 契约（§2.1 / §3.3）。
//!
//! 4 原语：`create_vm` / `get_vm` / `delete_vm` / `list_vm`。
//! 回收边界：VM 进程由本层回收；netns / ext4 / IP 租约由编排层调网络、存储层回收，
//! 职责不重叠。

use std::os::fd::RawFd;

/// VM 标识。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct VmId(pub u64);

/// VM 生命周期状态（§3.3）。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VmLifecycle {
    Creating,
    Restoring,
    Running,
    Degraded,
    Stopping,
    Stopped,
}

/// VM 实际态（由 driver `get_vm` 返回，供 reconcile 对账声明态 vs 实际态）。
#[derive(Debug, Clone)]
pub struct VmStatus {
    pub started: bool,
    pub healthy: bool,
    pub lifecycle: VmLifecycle,
}

/// 每 VM 的盘拓扑覆盖：把可写层 / 云盘 PATCH 进 snapshot 预留的 drive slot（§3.3 / §8.2）。
#[derive(Debug, Clone, Default)]
pub struct VmSpec {
    /// per-VM 可写 ext4 路径。
    pub rw_layer_path: Option<String>,
    /// per-VM 云盘块设备。
    pub cloud_disk_dev: Option<String>,
}

/// Firecracker 原语层错误。
#[derive(Debug, thiserror::Error)]
pub enum DriverError {
    #[error("vm not found: {0}")]
    NotFound(u64),
    #[error("vm already exists: {0}")]
    Exists(u64),
    #[error("snapshot error: {0}")]
    Snapshot(String),
    #[error("firecracker api error: {0}")]
    FirecrackerApi(String),
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
    #[error("{0}")]
    Other(String),
}

/// 编排层 → Firecracker 原语层接口（§2.1）。
///
/// `create_vm` 原子幂等：同 `(type_id, netns)` 已在建则返回旧 `VmId`；
/// `delete_vm` 幂等：删不存在返回 `Ok`，不保证立即停止，调用方轮询 `get_vm` 到 `Stopped`。
#[async_trait::async_trait]
pub trait FirecrackerDriver: Send + Sync {
    /// 原子幂等建 VM。`type_id` 决定 vCPU/mem/rootfs/drive 拓扑；
    /// `spec` 把 per-VM 可写层 / 云盘 PATCH 进 snapshot 预留的 drive slot；
    /// 就绪时写 `event_fd` 通知。
    async fn create_vm(
        &self,
        netns_path: &str,
        type_id: u8,
        spec: VmSpec,
        event_fd: RawFd,
    ) -> Result<VmId, DriverError>;

    async fn get_vm(&self, id: VmId) -> Result<VmStatus, DriverError>;

    async fn delete_vm(&self, id: VmId) -> Result<(), DriverError>;

    async fn list_vm(&self) -> Result<Vec<VmStatus>, DriverError>;
}

//! 编排层 → 网络层 契约（§2.2 / §3.4）。
//!
//! 为每 VM 建 netns + tap + IP / 路由 / NAT，确保 snapshot 克隆的网络可确定性重建。
//! 所有进 netns 的 syscall 关进 `spawn_blocking` 专用线程（RAII guard 还原），见 §3.4。

/// 网络上下文：建好后返回，供 snapshot 克隆确定性重建，`teardown` 据此幂等回收。
#[derive(Debug, Clone)]
pub struct NetConfig {
    /// `/var/run/netns/oas-<sandbox_id>`。
    pub netns_path: String,
    /// 克隆间保持一致，让 guest 无感。
    pub tap_name: String,
    pub mac: String,
    pub pod_ip: String,
    pub gateway: String,
    pub lease: oas_types::IpLease,
}

/// 网络层错误。
#[derive(Debug, thiserror::Error)]
pub enum NetError {
    #[error("io: {0}")]
    Io(#[from] std::io::Error),
    #[error("ipam exhausted: {0}")]
    IpamExhausted(String),
    #[error("{0}")]
    Other(String),
}

/// 编排层 → 网络层接口（§2.2）。
///
/// `setup` 建 netns + tap + 配 IP/路由/NAT，返回网络上下文；
/// `teardown` 幂等回收 netns / tap / 释放 IP 租约。
#[async_trait::async_trait]
pub trait NetworkManager: Send + Sync {
    async fn setup(&self, sandbox_id: &str) -> Result<NetConfig, NetError>;

    async fn teardown(&self, net: &NetConfig) -> Result<(), NetError>;
}

//! 编排层 → 存储层 契约（§2.3 / §3.5）。
//!
//! 按 `type` 制备每 VM 可写 ext4（COW/overlay over base，高密度关键）、绑定云盘、清理。

/// 盘配置：`provision` 返回，`cleanup` 据此幂等清理。
#[derive(Debug, Clone, Default)]
pub struct DiskConfig {
    /// `/var/lib/oas/rw/<sandbox_id>.ext4`。
    pub rw_layer_path: Option<String>,
    /// `/dev/xxx`，来自 annotation。
    pub cloud_disk_dev: Option<String>,
}

/// 存储层错误。
#[derive(Debug, thiserror::Error)]
pub enum StorageError {
    #[error("io: {0}")]
    Io(#[from] std::io::Error),
    #[error("cloud disk not found: {0}")]
    CloudDiskNotFound(String),
    #[error("{0}")]
    Other(String),
}

/// 编排层 → 存储层接口（§2.3）。
///
/// `provision` 按 type 制备每 VM 可写 ext4（COW/overlay），解析 annotation 里的云盘设备；
/// `cleanup` 幂等清理可写层文件、解绑云盘。
#[async_trait::async_trait]
pub trait StorageManager: Send + Sync {
    async fn provision(
        &self,
        sandbox_id: &str,
        type_id: u8,
        cloud_disk_ref: Option<&str>,
    ) -> Result<DiskConfig, StorageError>;

    async fn cleanup(&self, disk: &DiskConfig) -> Result<(), StorageError>;
}

