fn parse_cidr(cidr: &str) -> Result<(u32, u8), StoreError> {
    let (ip, prefix) = cidr.split_once('/').ok_or_else(|| StoreError::Other(format!("bad cidr: {cidr}")))?;
    let octets: Vec<u8> = ip.split('.').map(|s| s.parse::<u8>()).collect::<Result<Vec<_>,_>>().map_err(|_| StoreError::Other(format!("bad cidr: {cidr}")))?;
    if octets.len() != 4 { return Err(...); }
    let ip_u32 = u32::from_be_bytes([octets[0],octets[1],octets[2],octets[3]]);
    let prefix: u8 = prefix.parse().map_err(...)?;
    Ok((ip_u32, prefix))
}
fn ip_to_string(ip: u32) -> String { let b = ip.to_be_bytes(); format!("{}.{}.{}.{}", b[0],b[1],b[2],b[3]) }
