fn lease_ip_in(tables: &mut MemoryTables, cidr: &str) -> Result<IpLease, StoreError> {
    let (base, prefix) = parse_cidr(cidr)?;
    let host_bits = 32 - prefix;
    if host_bits == 0 { return Err(StoreError::Db("ipam exhausted: /32".into())); }
    let count = 1u64 << host_bits;  // total addresses
    let network = base & mask(prefix);
    // skip network (first) and broadcast (last) when host_bits >= 2
    let (start_off, end_off) = if host_bits >= 2 { (1u64, count - 1) } else { (0u64, count) }; // /31: use both
    for off in start_off..end_off {
        let candidate = network.wrapping_add(off as u32);
        let ip = ip_to_string(candidate);
        if !tables.ipam.contains_key(&ip) {
            let lease = IpLease { ip: ip.clone(), cidr: cidr.to_string(), sandbox_id: String::new() };
            tables.ipam.insert(ip, lease.clone());
            return Ok(lease);
        }
    }
    Err(StoreError::Db(format!("ipam exhausted: {cidr}")))
}
