    fn lease_ip(&self, cidr: &str) -> Result<IpLease, StoreError> {
        let mut wtxn = self.db.begin_write().map_err(map_err)?;
        let result = {
            let mut t = wtxn.open_table(IPAM).map_err(map_err)?;
            lease_ip_redb(&mut t, cidr)
