        match t.get(id).map_err(map_err)? {
            Some(g) => serde_json::from_slice(g.value())
                .map_err(|e| StoreError::Db(e.to_string())),
            None => Err(StoreError::NotFound(format!("sandbox {id}"))),
        }
    }

