        let mut out = Vec::new();
        for item in t.iter().map_err(map_err)? {
            let (_k, v) = item.map_err(map_err)?;
            let rec: ContainerRecord =
                serde_json::from_slice(v.value()).map_err(|e| StoreError::Db(e.to_string()))?;
