use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::Arc;

pub trait Clock: Send + Sync {
    fn now_unix_secs(&self) -> i64;
}

pub struct SystemClock;
impl Clock for SystemClock {
    fn now_unix_secs(&self) -> i64 {
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0)
    }
}

pub struct FakeClock {
    now: Arc<AtomicI64>,
}
impl FakeClock {
    pub fn new(start: i64) -> Self { Self { now: Arc::new(AtomicI64::new(start)) } }
    pub fn advance_to(&self, t: i64) { self.now.store(t, Ordering::Relaxed); }
    pub fn tick(&self) -> i64 { self.now.fetch_add(1, Ordering::Relaxed) + 1 }  // hmm
}
impl Clock for FakeClock {
    fn now_unix_secs(&self) -> i64 { self.now.load(Ordering::Relaxed) }
}
```
