}

impl Default for SandboxTypeTable {
    fn default() -> Self {
        Self {
            entries: [
                SandboxType {
                    type_id: 0,
                    vcpu: 1,
                    mem_mib: 512,
                    snapshot_path: "base-0.snap".into(),
                    rootfs_ro: "base-0.ext4".into(),
                    has_rw_layer: false,
