    if let Some(existing) = self.store.get_sandbox_by_uid(&req.metadata.uid).map_err(map_store_err)? {
        if existing.state == SandboxState::Ready {
            return Ok(existing.sandbox_id);
        } else {
            return Err(OasError::Conflict(format!("sandbox {} exists but not ready; remove first", existing.sandbox_id)));
        }
    }
    let ty = self.types.get(req.type_id)?;
    // 云盘一致性
    if ty.has_cloud_disk && req.cloud_disk_ref.is_none() {
        return Err(OasError::InvalidArgument(format!("type {} requires cloud-disk annotation", req.type_id)));
    }
    if !ty.has_cloud_disk && req.cloud_disk_ref.is_some() {
        return Err(OasError::InvalidArgument(format!("type {} does not accept cloud-disk", req.type_id)));
    }
    let sandbox_id = self.id_gen.sandbox_id();
    // net.setup (内部 lease_ip)
    let net_cfg = self.net.setup(&sandbox_id).await.map_err(map_net_err)?;
