    })?;
    // driver.create_vm
    let spec = VmSpec { rw_layer_path: disk.rw_layer_path.clone(), cloud_disk_dev: disk.cloud_disk_dev.clone() };
    let vm_id = match self.driver.create_vm(&net_cfg.netns_path, req.type_id, spec, -1).await {
        Ok(id) => id,
        Err(e) => {
            let oe = map_driver_err(e);
            self.rollback_after_create(&net_cfg, &disk, None).await;
            return Err(oe);
        }
    };
    // readiness
    if let Err(oe) = self.readiness.wait_ready(vm_id, READINESS_TIMEOUT).await {
        self.rollback_after_create(&net_cfg, &disk, Some(vm_id)).await;
        return Err(oe);
