#[tokio::test]
async fn e2e_run_sandbox_idempotent_by_uid() {
    let env = TestEnv::new();
    let mut c = setup(&env).await;
    let id1 = run_pod(&mut c.rt, "uid-1").await;
    let id2 = run_pod(&mut c.rt, "uid-1").await;
