#[tokio::test]
async fn e2e_remove_pod_sandbox_idempotent() {
    let env = TestEnv::new();
    let mut c = setup(&env).await;
    let sb_id = run_pod(&mut c.rt, "uid-1").await;
    c.rt
        .stop_pod_sandbox(StopPodSandboxRequest {
            pod_sandbox_id: sb_id.clone(),
