#[tokio::test]
async fn e2e_kubelet_protocol_sandbox_lifecycle() {
    // 模拟 kubelet 对一个沙箱的 CRI 协议交互（启动→稳态→停止→删除）。
    // 目的：证明 mock 后端的 API+Manager+Store 三层在协议层满足 kubelet，
    // 不依赖真实 firecracker（driver/net/storage 为 mock）。
    let env = TestEnv::new();
    let mut c = setup(&env).await;

    // 1) kubelet 启动握手：Version + Status(RuntimeReady/NetworkReady)
    let v = c.rt.version(VersionRequest { version: "0.1.0".into() }).await.unwrap().into_inner();
    assert_eq!(v.runtime_name, "only-agent-sandbox");
    let s = c.rt.status(StatusRequest::default()).await.unwrap().into_inner();
    let conds = s.status.unwrap().conditions;
    assert!(conds.iter().any(|x| x.r#type == "RuntimeReady" && x.status));
    assert!(conds.iter().any(|x| x.r#type == "NetworkReady" && x.status));

    // 2) ImageFsInfo：kubelet 周期性查磁盘防驱逐 → 返回"很空"假值
    let fs = c.img.image_fs_info(ImageFsInfoRequest::default()).await.unwrap().into_inner();
    assert!(!fs.image_filesystems.is_empty());

    // 3) RunPodSandbox（type=0，数字注解）→ READY + pod_ip
    let sb_id = run_pod(&mut c.rt, "uid-kubelet").await;
    let st = c.rt.pod_sandbox_status(PodSandboxStatusRequest { pod_sandbox_id: sb_id.clone(), ..Default::default() }).await.unwrap().into_inner().status.unwrap();
    assert_eq!(st.state, PodSandboxState::SandboxReady as i32);
    assert!(!st.network.unwrap().ip.is_empty());

    // 4) PLEG 稳态：多次 ListPodSandbox + PodSandboxStatus，状态恒定、id 不变、不打 driver（红线③）
    let create_count_before = env.driver.create_count();
    for _ in 0..3 {
        let items = c.rt.list_pod_sandbox(ListPodSandboxRequest { filter: None }).await.unwrap().into_inner().items;
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].id, sb_id);
        assert_eq!(items[0].state, PodSandboxState::SandboxReady as i32);
        let st = c.rt.pod_sandbox_status(PodSandboxStatusRequest { pod_sandbox_id: sb_id.clone(), ..Default::default() }).await.unwrap().into_inner().status.unwrap();
        assert_eq!(st.state, PodSandboxState::SandboxReady as i32);
    }
    // PLEG 读路径零 driver 调用
    assert_eq!(env.driver.create_count(), create_count_before);
    assert_eq!(env.driver.get_count(), 0);
    assert_eq!(env.driver.list_count(), 0);

    // 5) StopPodSandbox → NotReady，仍出现在 List（kubelet 列出已停止 pod）
    c.rt.stop_pod_sandbox(StopPodSandboxRequest { pod_sandbox_id: sb_id.clone() }).await.unwrap();
    let st = c.rt.pod_sandbox_status(...).await.unwrap().into_inner().status.unwrap();
    assert_eq!(st.state, PodSandboxState::SandboxNotready as i32);
    let items = c.rt.list_pod_sandbox(...).await.unwrap().into_inner().items;
    assert_eq!(items.len(), 1);

    // 6) RemovePodSandbox → 之后 NotFound + List 空
    c.rt.remove_pod_sandbox(RemovePodSandboxRequest { pod_sandbox_id: sb_id.clone() }).await.unwrap();
    let err = c.rt.pod_sandbox_status(...).await.unwrap_err();
    assert_eq!(err.code(), tonic::Code::NotFound);
    let items = c.rt.list_pod_sandbox(...).await.unwrap().into_inner().items;
