// header
if let Some(authority) = pseudo.authority {
    // PATCH (oas-runtime): relax :authority validation for Unix-domain
    // socket clients. grpc-go (crictl/kubelet) sends the socket path
    // (e.g. "/tmp/oas.sock") as :authority; it contains '/' and fails
    // URI authority parsing. Drop the authority on parse failure
    // instead of resetting the stream with PROTOCOL_ERROR. CRI/tonic
    // handlers do not rely on :authority.
    let maybe_authority = uri::Authority::from_maybe_shared(authority.clone().into_inner());
    parts.authority = match maybe_authority {
        Ok(a) => Some(a),
        Err(_) => None,
    };
}

